-- See https://wiki.hyprland.org/Configuring/Keywords/

local mainMod = "SUPER"

-- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hyprland.org/Configuring/Binds/ for more

hl.bind(mainMod .. " + " .. "T", hl.dsp.exec_cmd("kitty"))
hl.bind(mainMod .. " + " .. "Q", hl.dsp.window.close())
hl.bind(mainMod .. " + " .. "F", hl.dsp.exec_cmd("thunar"))
hl.bind(mainMod .. " + " .. "B", hl.dsp.exec_cmd("firefox"))
hl.bind(mainMod .. " + " .. "P", hl.dsp.window.float())

hl.bind(
	mainMod .. " + " .. "R",
	hl.dsp.exec_cmd("rofi -show drun -theme ${HOME}/.config/rofi/launchers/type-6/style-7.rasi")
)

hl.bind(mainMod .. " + " .. "F11", hl.dsp.window.fullscreen())

hl.bind(
	mainMod .. " + " .. "V",
	hl.dsp.exec_cmd(
		"rofi -modi clipboard:${HOME}/.config/cliphist/cliphist-rofi-img -theme ${HOME}/.config/rofi/launchers/type-6/style-7.rasi -show clipboard -show-icons"
	)
)

hl.bind(mainMod .. " + " .. "L", hl.dsp.exec_cmd("hyprlock"))
hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "L", hl.dsp.exec_cmd("wlogout"))
hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "V", hl.dsp.exec_cmd("cliphist wipe"))

hl.bind(
	mainMod .. " + " .. "PERIOD",
	hl.dsp.exec_cmd(
		"rofi -modi emoji -theme ${HOME}/.config/rofi/launchers/type-2/style-1.rasi -show emoji -show-icons false"
	)
)

hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "P", hl.dsp.exec_cmd("hyprpicker -f hex -n -a"))
hl.bind("Print", hl.dsp.exec_cmd('grim -g "$(slurp -d)" - | wl-copy'))

-- Volume control
